alter function fn_GetStoreFullfilledOrders (@store_id int ,@max_processing_days int)
 returns table as
 return( 
 select order_id,
 datediff(day,order_date, shipped_date) as shipped_orders from sales.orders where store_id = @store_id 
										and datediff(day,order_date, shipped_date) <= @max_processing_days and shipped_date is not null
 )
 select * from fn_GetStoreFullfilledOrders(2,2)





 -- ==========================4==============================
alter function fn_GetCustomerDelayedOrders(@customer_id int)
 returns table as
 return(
 select customer_id, order_id from sales.orders where (shipped_date > required_date or shipped_date is null) and customer_id = @customer_id
 )
 select * from  fn_GetCustomerDelayedOrders(175)


